const float pi = 3.14159265;
const vec3 color1 = vec3(0.25, 0.55, 0.85);
const vec3 color2 = vec3(0.25, 0.5, 0.75);

float circularGradientMask(
    vec2 uv)
{
    return 1.0-length(uv);
}

float radialGradientMask(
    vec2 uv)
{
    return ((atan(uv.y, uv.x) / pi) / 2.0) + 0.5;
}

float repeat(
    float value,
    float multiplier)
{
    return mod(value * multiplier, 1.0);
}

void mainImage(
    out vec4 fragColor,
    in vec2 fragCoord )
{
    // Normalized pixel coordinates (from -1.0 to +1.0)
    vec2 uv = (fragCoord - (iResolution.xy / 2.0)) / (min(iResolution.x, iResolution.y) / 2.0);

    // Time varying spiral
    float mixT = round(repeat((radialGradientMask(uv) + (iTime / 2.5)) + (circularGradientMask(uv) * 2.5), 1.0));
    vec3 col = mix(color1, color2, mixT);

    // Output to screen
    fragColor = vec4(col,1.0);
}
